{"query": "
SELECT table_schema, table_name, table_type
FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'auth', 'storage', 'extensions', 'realtime', 'pgbouncer', 'pgsodium', 'vault')
ORDER BY table_schema, table_name;
"}

